import { useEffect, useRef, useCallback, useState } from "react";
import styled from "styled-components";

import { DivFlexColumn, DivFlexRow, StyledLabel } from "./elements/formelements";
import TextAreaAutogrow from "./TextAreaAutogrow";

interface HighlightRule {
    pattern: RegExp;
    style: React.CSSProperties;
}

interface StyledTextAreaProps {
    readOnly?: boolean;
    hasHighlighting?: boolean;
}

const StyledTextArea = styled(TextAreaAutogrow).withConfig({
    shouldForwardProp: (prop) => !["hasHighlighting"].includes(prop),
})<StyledTextAreaProps>`
    width: 100%;
    resize: vertical;
    & textarea {
        ${({ hasHighlighting }) =>
            hasHighlighting
                ? `
      line-height: 155%;
      min-height: calc(1.55em * 5 + 8px);
      background-color: transparent;
      color: transparent;
      caret-color: black;
      
      &::selection {
        background-color: rgba(0, 123, 255, 0.3) !important;
      }
    `
                : ""}
        position: relative;
        z-index: 1;
    }
`;

const HighlightOverlay = styled.div`
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 3px;
    width: 100%;
    padding: 4px;
    pointer-events: none;
    font-family: inherit;
    font-size: inherit;
    line-height: 155%;
    margin: inherit;
    border: 1px solid transparent;
    white-space: pre-wrap;
    word-wrap: break-word;
    overflow: visible;
    z-index: 0;
    transform: translateY(var(--scroll-offset, 0px));
`;

const TextAreaContainer = styled.div`
    position: relative;
    width: 100%;
    overflow: hidden;
`;

const BackgroundDiv = styled.div`
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    width: 100%;
    z-index: -1;
    border: 1px solid transparent;
`;

interface TextAreaProps {
    label?: string;
    ariaLabel: string;
    value: string;
    onChange: (value: string) => void;
    readOnly?: boolean;
    defaultHeightRows?: number;
    highlightRules?: HighlightRule[];
    validate?: (value: string) => true | string | string[] | null | undefined;
}

const TextAreaLabeled: React.FC<TextAreaProps> = ({
    label,
    ariaLabel,
    value,
    onChange,
    readOnly = false,
    defaultHeightRows,
    highlightRules,
    validate,
}) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const overlayRef = useRef<HTMLDivElement>(null);
    const [scrollbarWidth, setScrollbarWidth] = useState(0);

    // set default values for optional props
    const rows = defaultHeightRows ? defaultHeightRows : 5;

    const hasHighlighting = highlightRules && highlightRules.length > 0;

    const renderHighlightedText = () => {
        if (!hasHighlighting) return null;

        interface HighlightElement {
            start: number;
            end: number;
            text: string;
            style: React.CSSProperties;
            ruleIndex: number;
        }

        // In the Text Area's string value, find all placeholder occurences as defined in the highlight rules
        const allPlaceholders: HighlightElement[] = [];

        highlightRules!.forEach((rule, ruleIndex) => {
            const matches = Array.from(value.matchAll(rule.pattern));
            matches.forEach((match) => {
                if (match.index !== undefined) {
                    allPlaceholders.push({
                        start: match.index,
                        end: match.index + match[0].length,
                        text: match[0],
                        style: rule.style,
                        ruleIndex,
                    });
                }
            });
        });

        allPlaceholders.sort((a, b) => a.start - b.start);

        // Create spans based on sorted matches
        const spans: JSX.Element[] = [];
        let lastPosition = 0;

        allPlaceholders.forEach((placeholder, placeholderIndex) => {
            // Add regular text before match (if any)
            if (placeholder.start > lastPosition) {
                spans.push(
                    <span key={`text-${lastPosition}-${placeholder.start}`}>
                        {value.slice(lastPosition, placeholder.start)}
                    </span>
                );
            }

            // Add highlighted placeholder (only if it doesn't overlap with previous)
            if (placeholder.start >= lastPosition) {
                spans.push(
                    <span key={`placeholder-${placeholder.ruleIndex}-${placeholderIndex}`} style={placeholder.style}>
                        {placeholder.text}
                    </span>
                );
                lastPosition = placeholder.end;
            }
        });

        // Add remaining normal text after all placeholders
        if (lastPosition < value.length) {
            spans.push(<span key={`text-${lastPosition}-end`}>{value.slice(lastPosition)}</span>);
        }

        return spans;
    };

    const updateScrollbarWidth = useCallback(() => {
        const textArea = containerRef.current?.querySelector("textarea");
        if (textArea) {
            const newScrollbarWidth = textArea.offsetWidth - textArea.clientWidth;
            setScrollbarWidth(newScrollbarWidth);
        }
    }, []);

    const handleScroll = useCallback(() => {
        const textArea = containerRef.current?.querySelector("textarea");
        if (textArea && overlayRef.current) {
            const scrollTop = textArea.scrollTop;
            overlayRef.current.style.setProperty("--scroll-offset", `-${scrollTop}px`);
        }
    }, []);

    useEffect(() => {
        const textArea = containerRef.current?.querySelector("textarea");
        if (textArea) {
            updateScrollbarWidth();

            const resizeObserver = new ResizeObserver(updateScrollbarWidth);
            resizeObserver.observe(textArea);

            textArea.addEventListener("scroll", handleScroll);

            return () => {
                resizeObserver.disconnect();
                textArea.removeEventListener("scroll", handleScroll);
            };
        }
    }, [handleScroll, updateScrollbarWidth]);

    return (
        <DivFlexRow>
            {label && (
                <DivFlexColumn>
                    <StyledLabel>{label}</StyledLabel>
                </DivFlexColumn>
            )}
            <DivFlexColumn fullWidth>
                <TextAreaContainer ref={containerRef}>
                    {hasHighlighting && (
                        <>
                            <BackgroundDiv />
                            <HighlightOverlay ref={overlayRef} style={{ paddingRight: `${2 + scrollbarWidth}px` }}>
                                {renderHighlightedText()}
                            </HighlightOverlay>
                        </>
                    )}
                    <StyledTextArea
                        ariaLabel={ariaLabel}
                        value={value}
                        readOnly={readOnly}
                        onChange={onChange}
                        rows={rows}
                        hasHighlighting={hasHighlighting}
                        validate={validate}
                    />
                </TextAreaContainer>
            </DivFlexColumn>
        </DivFlexRow>
    );
};

export default TextAreaLabeled;
